CREATE OR REPLACE FUNCTION trip_private.surprise_night_game(p_trip uuid,p_week integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_used integer[]; v_game integer; v_n public.game_nights; BEGIN IF auth.uid() IS NULL OR NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF; SELECT * INTO v_n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE; IF NOT FOUND OR v_n.game_number IS NOT NULL OR v_n.skipped OR v_n.starts_at<=now() OR NOT(trip_private.is_leader(p_trip,auth.uid()) OR v_n.host_id=auth.uid()) THEN RAISE EXCEPTION 'Only the host or a leader can choose an upcoming night'; END IF; SELECT coalesce(used_games,'{}'::integer[]) INTO v_used FROM public.trip_play_state WHERE trip_id=p_trip; SELECT number INTO v_game FROM public.game_catalog WHERE NOT(number=ANY(coalesce(v_used,'{}'::integer[]))) ORDER BY random() LIMIT 1; IF v_game IS NULL THEN SELECT number INTO v_game FROM public.game_catalog ORDER BY random() LIMIT 1; END IF; IF v_game IS NULL THEN RAISE EXCEPTION 'No game available'; END IF; PERFORM trip_private.pick_night_game(p_trip,p_week,v_game); UPDATE public.game_pick_log SET method='surprise' WHERE id=(SELECT max(id) FROM public.game_pick_log WHERE trip_id=p_trip AND week_number=p_week AND actor=auth.uid()); RETURN v_game; END $$; REVOKE ALL ON FUNCTION trip_private.surprise_night_game(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION trip_private.surprise_night_game(uuid,integer) TO authenticated; CREATE OR REPLACE FUNCTION public.surprise_night_game(p_trip uuid,p_week integer) RETURNS integer LANGUAGE sql SET search_path=public AS $$ SELECT trip_private.surprise_night_game(p_trip,p_week) $$; REVOKE ALL ON FUNCTION public.surprise_night_game(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.surprise_night_game(uuid,integer) TO authenticated;